def _bottles(n):
    if n == 0:
        return "No more bottles of beer"
    if n == 1:
        return "1 bottle of beer"
    return f"{n} bottles of beer"


def recite(start, take=1):
    lines = []
    for n in range(start, start - take, -1):
        if lines:
            lines.append("")
        if n > 1:
            lines.append(
                f"{_bottles(n)} on the wall, {_bottles(n).lower()}."
            )
            lines.append(
                f"Take one down and pass it around, "
                f"{_bottles(n - 1).lower()} on the wall."
            )
